insert into public.vibecode_catalog (slug,category,title,summary,kind,prototype,next_step,review,prompt,sort_order,published) values ('neon-dodge','Games','Seu primeiro minigame','Uma mecânica simples, controles precisos e vontade de tentar de novo.','IA na construção','Um jogo 2D de desviar de obstáculos com placar, reinício e três dificuldades. Comece com uma única tela.','Peça suporte a toque e compare a experiência no celular. Depois, experimente um escudo de uso único.','Confira colisão, pausa, reinício e limites da tela. O jogo deve continuar funcionando sem consultar um modelo de IA.','Crie um minigame de desviar de obstáculos em um único index.html, sem dependências externas. Use setas ou A/D, pontuação por tempo, fim de jogo por colisão e reinício completo. Inclua instruções e visual neon com bom contraste. Abra e teste a primeira partida, a colisão e o reinício. Relate limitações.',1,true),('npc','Games','Personagens que conversam','Um NPC com personalidade, contexto e respostas para o jogador.','IA dentro do aplicativo','Uma conversa com um personagem original. Defina o mundo, o que ele sabe e como deve responder.','Conecte uma API de modelo no servidor e envie somente o contexto necessário. Limite o tamanho das respostas.','Avalie respostas inesperadas, conteúdo impróprio, tempo de resposta e custo por conversa. Proteja a chave da API no servidor.','Planeje e implemente a interface de um NPC para um jogo de exploração. Defina sua personalidade e limite suas respostas ao contexto do mundo. Separe a integração com o modelo em uma rota no servidor. Não exponha credenciais. Se não houver API configurada, informe isso claramente. Inclua estados de espera e erro.',2,true),('evento','Aplicativos','O evento no seu bolso','Programação, trilhas e informações em um lugar que cabe na mão.','IA na construção','Uma agenda do evento com filtros por tema e informações de cada atividade. Use dados de exemplo identificados até receber a programação oficial.','Salve a programação em um banco de dados e permita leitura pública. Edições ficam restritas aos responsáveis.','Confira fuso horário, nomes das atividades, telas pequenas e permissões de edição. Não invente a programação do evento.','Crie um aplicativo responsivo de agenda de evento com filtros por trilha. Use uma coleção de dados de exemplo claramente identificada. Mostre nome, horário e local. Modele um banco de dados com acesso público só de leitura e edição restrita. Teste filtros e navegação no celular.',3,true),('quiz','Aplicativos','Aprender vira um desafio','Um quiz para estudar, treinar a equipe ou reunir a comunidade.','IA na construção','Um quiz de cinco perguntas revisadas, com uma resposta correta por questão e explicação no final.','Use IA para rascunhar novas perguntas, revise os fatos e salve o conteúdo aprovado no banco de dados.','Valide as respostas e as explicações. Confira se reiniciar zera o resultado e se o quiz funciona com teclado.','Crie um quiz de cinco perguntas sobre desenvolvimento de jogos para iniciantes. Inclua pontuação, explicação das respostas e reinício. Separe as perguntas da interface. Marque o conteúdo como rascunho para revisão e informe quais fatos precisam de conferência. Garanta navegação por teclado.',4,true),('conteudo','Criação','Um estúdio de conteúdo','Rascunhos de posts, roteiros e variações a partir de um briefing.','IA dentro do aplicativo','Um formulário com público, objetivo, tom e formato. O resultado é um rascunho editável, nunca uma publicação automática.','Conecte um modelo no servidor e permita comparar versões. Salve apenas o que a pessoa escolher manter.','Revise fatos, referências e direitos de uso. Mostre erros de geração e evite divulgar informações privadas no briefing.','Construa uma interface para gerar rascunhos de posts a partir de público, objetivo, tom e formato. O usuário deve revisar e editar antes de exportar. Integre o modelo no servidor, se houver credenciais configuradas. Inclua limite de uso, estados de espera e erro. Não publique automaticamente.',5,true),('tarefas','Aplicativos','Uma ferramenta para sua rotina','Um painel pequeno que resolve um problema recorrente da sua equipe.','IA na construção','Uma lista de tarefas com responsável, prazo e status. Comece pelo fluxo de criar, concluir e consultar.','Adicione autenticação e acesso por equipe quando houver dados reais. Peça à IA para explicar as regras de permissão.','Teste quem pode ler e editar cada tarefa. Evite dados pessoais no protótipo e valide a persistência antes de compartilhar.','Crie um organizador de tarefas com título, prazo, responsável e status. Implemente filtros e estados vazios claros. Use dados fictícios no protótipo. Antes de conectar dados reais, proponha autenticação e regras de acesso por equipe. Teste criação, edição, conclusão e recarregamento.',6,true);
